import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import * as fs from "fs";
import * as path from "path";

async function main() {
  const trialIdPath = "/logs/artifacts/trial_id";
  const trialId = fs.readFileSync(trialIdPath, "utf-8").trim();

  const normalize = (name: string) => {
    return name.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
  };

  const agentNames = [1, 2, 3, 4].map((i) => `pool-agent-${trialId}-${i}`);
  const normalizedNames = agentNames.map(normalize);

  console.log(`Provisioning workspaces: ${normalizedNames.join(", ")}`);

  // 1. Provision workspaces concurrently
  const workspaces = await Promise.all(
    normalizedNames.map((name) =>
      createWorkspace(name, {
        ttl: { days: 1 },
        credentials: { role: "Editor" },
      })
    )
  );

  try {
    // 2. Upload init.txt to each workspace concurrently
    await Promise.all(
      workspaces.map(async (ws, index) => {
        const s3 = new S3Client({
          endpoint: "REDACTED",
          region: "REDACTED",
          credentials: {
            accessKeyId: ws.credentials.accessKeyId,
            secretAccessKey: ws.credentials.secretAccessKey,
          },
        });

        const name = normalizedNames[index];
        await s3.send(
          new PutObjectCommand({
            Bucket: ws.bucket,
            Key: "init.txt",
            Body: name,
          })
        );
        console.log(`Uploaded init.txt to ${name} (${ws.bucket})`);
      })
    );

    // 3. Write summary file
    const poolSummary = workspaces.map((ws, index) => ({
      name: normalizedNames[index],
      bucket: ws.bucket,
    }));

    const summaryPath = "/home/user/ws-pool/pool.json";
    fs.writeFileSync(summaryPath, JSON.stringify(poolSummary, null, 2));
    console.log(`Summary written to ${summaryPath}`);

  } finally {
    // 4. Teardown workspaces resiliently
    console.log("Tearing down workspaces...");
    const results = await Promise.allSettled(
      workspaces.map((ws) => teardownWorkspace(ws.name))
    );

    results.forEach((result, index) => {
      if (result.status === "rejected") {
        console.error(`Failed to teardown workspace ${normalizedNames[index]}:`, result.reason);
      } else {
        console.log(`Successfully tore down workspace ${normalizedNames[index]}`);
      }
    });
  }
}

main().catch((err) => {
  console.error("Script failed:", err);
  process.exit(1);
});

